CREATE TABLE IF NOT EXISTS "public"."video_report_delivery_acknowledgements" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "delivery_id" "uuid" NOT NULL,
    "acknowledged_by_label" "text" NOT NULL,
    "acknowledgement_text" "text" NOT NULL,
    "acknowledged_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."video_report_delivery_acknowledgements" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."acknowledge_video_report_delivery"("target_delivery_id" "uuid", "acknowledgement_text" "text") RETURNS "public"."video_report_delivery_acknowledgements"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  acknowledgement_row public.video_report_delivery_acknowledgements;
  authorised_delivery_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  if coalesce(pg_catalog.btrim(acknowledgement_text), '') = '' then
    raise exception 'Acknowledgement text is required';
  end if;

  update public.video_report_deliveries
  set delivery_status = 'acknowledged',
      updated_at = pg_catalog.now()
  where id = target_delivery_id
    and (
      internal_recipient_user_id = auth.uid()
      or public.is_video_admin(array['super_admin'])
    )
  returning id into authorised_delivery_id;

  if authorised_delivery_id is null then
    raise exception 'Delivery not found or not authorised';
  end if;

  insert into public.video_report_delivery_acknowledgements (
    delivery_id,
    acknowledged_by_label,
    acknowledgement_text
  )
  values (
    authorised_delivery_id,
    auth.uid()::text,
    acknowledgement_text
  )
  returning * into acknowledgement_row;

  return acknowledgement_row;
end;
$$;


ALTER FUNCTION "public"."acknowledge_video_report_delivery"("target_delivery_id" "uuid", "acknowledgement_text" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."personal_ai_flow_versions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "flow_id" "text" NOT NULL,
    "version" "text" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "title" "text" NOT NULL,
    "risk_level" "text" NOT NULL,
    "category" "text" NOT NULL,
    "trigger_phrases" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "assistant_goal" "text" NOT NULL,
    "first_response" "text" NOT NULL,
    "core_script" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "follow_up_questions" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "escalation_type" "text" NOT NULL,
    "documentation_template_key" "text" NOT NULL,
    "safe_reply_template_keys" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "prompt_template_keys" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "ui_copy_keys" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "validator_profile_key" "text" NOT NULL,
    "jurisdiction_scope" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "effective_from" timestamp with time zone,
    "effective_to" timestamp with time zone,
    "change_summary" "text" NOT NULL,
    "release_checks" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "personal_ai_flow_versions_change_summary_check" CHECK ((("char_length"("change_summary") >= 10) AND ("char_length"("change_summary") <= 1000))),
    CONSTRAINT "personal_ai_flow_versions_check" CHECK ((("risk_level" <> 'critical'::"text") OR ("cardinality"("jurisdiction_scope") > 0))),
    CONSTRAINT "personal_ai_flow_versions_follow_up_questions_check" CHECK (("cardinality"("follow_up_questions") <= 1)),
    CONSTRAINT "personal_ai_flow_versions_risk_level_check" CHECK (("risk_level" = ANY (ARRAY['low'::"text", 'medium'::"text", 'high'::"text", 'critical'::"text"]))),
    CONSTRAINT "personal_ai_flow_versions_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'in_review'::"text", 'approved'::"text", 'active'::"text", 'deprecated'::"text", 'rejected'::"text", 'rolled_back'::"text"]))),
    CONSTRAINT "personal_ai_flow_versions_version_check" CHECK (("version" ~ '^[0-9]+\.[0-9]+\.[0-9]+(?:-[a-z0-9.-]+)?$'::"text"))
);


ALTER TABLE "public"."personal_ai_flow_versions" OWNER TO "postgres";


COMMENT ON TABLE "public"."personal_ai_flow_versions" IS 'Immutable after approval/release. Critical versions require independent human approvals before activation.';



CREATE OR REPLACE FUNCTION "public"."activate_personal_ai_flow_version"("target_id" "uuid", "activation_reason" "text") RETURNS "public"."personal_ai_flow_versions"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare target public.personal_ai_flow_versions; approval_count integer; prior_version text;
begin
  if not public.current_user_has_role('admin') then raise exception 'Administrator access required'; end if;
  select * into target from public.personal_ai_flow_versions where id = target_id for update;
  if target.status <> 'approved' then raise exception 'Only approved versions can be activated'; end if;
  select count(distinct approver_user_id) into approval_count from public.personal_ai_flow_version_approvals where flow_version_id = target.id and decision = 'approved';
  if approval_count < (case when target.risk_level = 'critical' then 2 else 1 end) then raise exception 'Required independent approvals are missing'; end if;
  if target.risk_level = 'critical' and not (target.release_checks @> '{"safety_tests":true,"clinical_signoff":true,"safeguarding_signoff":true,"jurisdiction_review":true,"rollback_tested":true}'::jsonb) then raise exception 'Critical release checklist is incomplete'; end if;
  select version into prior_version from public.personal_ai_flow_versions where flow_id = target.flow_id and status = 'active' for update;
  update public.personal_ai_flow_versions set status = 'deprecated', effective_to = now(), updated_at = now() where flow_id = target.flow_id and status = 'active';
  update public.personal_ai_flow_versions set status = 'active', effective_from = now(), effective_to = null, updated_at = now() where id = target.id returning * into target;
  insert into public.personal_ai_flow_version_audit_logs(flow_version_id,flow_id,previous_version,new_version,action,actor_user_id,reason) values(target.id,target.flow_id,prior_version,target.version,'activated',auth.uid(),activation_reason);
  return target;
end; $$;


ALTER FUNCTION "public"."activate_personal_ai_flow_version"("target_id" "uuid", "activation_reason" "text") OWNER TO "postgres";


