CREATE OR REPLACE FUNCTION "public"."audit_row_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_tenant_id uuid;
  v_record_id uuid;
  v_previous jsonb;
  v_resulting jsonb;
  v_event_type text;
begin
  if tg_op = 'INSERT' then
    v_resulting := to_jsonb(new);
    v_previous := null;
    v_event_type := 'record_created';
    v_record_id := new.id;
    v_tenant_id := nullif(v_resulting ->> 'tenant_id', '')::uuid;
  elsif tg_op = 'UPDATE' then
    v_previous := to_jsonb(old);
    v_resulting := to_jsonb(new);
    v_event_type := 'record_updated';
    v_record_id := new.id;
    v_tenant_id := coalesce(nullif(v_resulting ->> 'tenant_id', '')::uuid, nullif(v_previous ->> 'tenant_id', '')::uuid);
  elsif tg_op = 'DELETE' then
    v_previous := to_jsonb(old);
    v_resulting := null;
    v_event_type := 'record_deleted';
    v_record_id := old.id;
    v_tenant_id := nullif(v_previous ->> 'tenant_id', '')::uuid;
  end if;

  insert into public.audit_events (
    audit_reference,
    tenant_id,
    event_category,
    event_type,
    target_table,
    target_record_id,
    actor_type,
    actor_user_id,
    actor_service,
    previous_state,
    resulting_state,
    previous_state_hash,
    resulting_state_hash
  )
  values (
    'AUD-' || gen_random_uuid()::text,
    v_tenant_id,
    'database_change',
    v_event_type,
    tg_table_schema || '.' || tg_table_name,
    v_record_id,
    case when auth.uid() is not null then 'user' else 'service' end,
    auth.uid(),
    case when auth.uid() is null then current_user else null end,
    v_previous,
    v_resulting,
    case when v_previous is null then null else encode(digest(v_previous::text, 'sha256'), 'hex') end,
    case when v_resulting is null then null else encode(digest(v_resulting::text, 'sha256'), 'hex') end
  );

  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "public"."audit_row_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bind_single_case_before_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  resolved_case_id uuid;
  case_count integer;
begin
  if new.case_id is not null then return new; end if;

  select count(distinct cm.case_id)
  into case_count
  from public.case_memberships cm
  where cm.user_id = auth.uid() and cm.status = 'active';

  select cm.case_id
  into resolved_case_id
  from public.case_memberships cm
  where cm.user_id = auth.uid() and cm.status = 'active'
  order by cm.case_id::text
  limit 1;

  if case_count = 0 then
    raise exception 'active case membership required';
  end if;
  if case_count > 1 then
    raise exception 'case_id required when user has multiple active case memberships';
  end if;

  new.case_id := resolved_case_id;
  return new;
end;
$$;


ALTER FUNCTION "public"."bind_single_case_before_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bootstrap_platform_tenant"("p_tenant_reference" "text", "p_tenant_slug" "text", "p_tenant_name" "text", "p_owner_user_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_tenant_id uuid;
  v_owner_role_id uuid;
begin
  insert into public.platform_tenants (
    tenant_reference,
    tenant_slug,
    tenant_name,
    tenant_type,
    tenant_status,
    activated_at
  )
  values (
    p_tenant_reference,
    p_tenant_slug,
    p_tenant_name,
    'standard',
    'active',
    now()
  )
  on conflict (tenant_reference) do update
  set tenant_slug = excluded.tenant_slug,
      tenant_name = excluded.tenant_name,
      tenant_status = 'active',
      updated_at = now()
  returning id into v_tenant_id;

  select id into v_owner_role_id
  from public.role_definitions
  where tenant_id is null and role_code = 'tenant_owner';

  insert into public.tenant_memberships (
    tenant_id,
    user_id,
    membership_type,
    membership_status,
    accepted_at
  )
  values (v_tenant_id, p_owner_user_id, 'tenant_owner', 'active', now())
  on conflict do nothing;

  if v_owner_role_id is not null then
    insert into public.role_assignments (
      tenant_id,
      user_id,
      role_definition_id,
      scope_type,
      assignment_status,
      assignment_reason
    )
    values (
      v_tenant_id,
      p_owner_user_id,
      v_owner_role_id,
      'tenant',
      'active',
      'bootstrap tenant owner'
    )
    on conflict do nothing;
  end if;

  return v_tenant_id;
end;
$$;


ALTER FUNCTION "public"."bootstrap_platform_tenant"("p_tenant_reference" "text", "p_tenant_slug" "text", "p_tenant_name" "text", "p_owner_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_developmental_stage"("p_date_of_birth" "date") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select case
    when p_date_of_birth is null then null
    when age(current_date, p_date_of_birth) < interval '3 years' then 'early_childhood'
    when age(current_date, p_date_of_birth) < interval '6 years' then 'preschool'
    when age(current_date, p_date_of_birth) < interval '13 years' then 'primary_school'
    when age(current_date, p_date_of_birth) < interval '18 years' then 'adolescent'
    else 'adult'
  end;
$$;


ALTER FUNCTION "public"."calculate_developmental_stage"("p_date_of_birth" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_access_video_report"("target_parent_user_id" "uuid", "requested_scope" "text" DEFAULT 'video_progress'::"text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select (select auth.uid()) = target_parent_user_id
    or is_video_admin(array['super_admin'])
    or (
      exists (
        select 1 from video_report_access_grants grant_row
        where grant_row.parent_user_id = target_parent_user_id
          and grant_row.reviewer_user_id = (select auth.uid())
          and grant_row.active = true
          and grant_row.expires_at > now()
          and (grant_row.access_scope = requested_scope or grant_row.access_scope = 'video_progress_and_evidence')
      )
      and has_active_video_report_authority(target_parent_user_id, (select auth.uid()), requested_scope)
    );
$$;


ALTER FUNCTION "public"."can_access_video_report"("target_parent_user_id" "uuid", "requested_scope" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_activate_platform_tenant_feature"("p_feature_flag_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.platform_tenant_feature_flags f
    join public.platform_feature_definitions d on d.id = f.feature_definition_id
    left join public.platform_tenant_subscriptions s
      on s.tenant_id = f.tenant_id
      and s.subscription_status = 'active'
    left join public.platform_tenant_license_plans lp on lp.id = s.license_plan_id
    where f.id = p_feature_flag_id
      and d.lifecycle_status = 'active'
      and (
        lp.id is null
        or lp.allowed_feature_codes = '{}'
        or d.feature_code = any(lp.allowed_feature_codes)
        or d.safety_critical = true
      )
      and f.governance_approved = true
      and not ((d.safety_critical = true or d.child_privacy_critical = true) and f.enabled = false)
      and coalesce(s.safety_access_preserved, true) = true
  );
$$;


ALTER FUNCTION "public"."can_activate_platform_tenant_feature"("p_feature_flag_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_approve_ai_change_request"("p_change_request_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.ai_change_requests cr
    where cr.id = p_change_request_id
      and cr.status in ('submitted', 'under_review')
      and not exists (
        select 1
        from public.ai_change_request_reviews rr
        where rr.change_request_id = cr.id
          and rr.outcome in ('rejected', 'changes_required')
      )
      and not exists (
        select 1
        from public.ai_change_deployment_gates g
        where g.change_request_id = cr.id
          and g.blocking = true
          and g.gate_status <> 'passed'
      )
  );
$$;


