        where r.candidate_id = c.id
          and r.outcome = 'failed'
      )
      and exists (
        select 1
        from public.ai_learning_example_quality_reviews r
        where r.candidate_id = c.id
          and r.review_type = 'privacy'
          and r.outcome in ('passed', 'waived')
      )
      and exists (
        select 1
        from public.ai_learning_example_quality_reviews r
        where r.candidate_id = c.id
          and r.review_type = 'bias'
          and r.outcome in ('passed', 'waived')
      )
  );
