    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    p_user_id = (select auth.uid())
    and exists (
      select 1
      from public.reports r
      where r.id = p_report_id
        and (
          r.requested_by = p_user_id
          or r.primary_author_id = p_user_id
          or r.current_reviewer_id = p_user_id
          or r.approved_by = p_user_id
          or (
            r.case_id is not null
            and public.has_case_permission(p_user_id, r.case_id, 'report.read')
          )
          or exists (
            select 1
            from public.report_recipients rr
            where rr.report_id = r.id
              and rr.recipient_user_id = p_user_id
              and rr.released_at is not null
              and rr.revoked_at is null
              and (rr.access_expires_at is null or rr.access_expires_at > now())
          )
        )
    );
$$;


ALTER FUNCTION "public"."can_read_report"("p_report_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_release_ai_deployment"("p_assurance_package_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.ai_release_assurance_packages p
    join public.ai_evaluation_plans ep on ep.id = p.evaluation_plan_id
    join public.ai_model_deployments d on d.id = p.deployment_id
    where p.id = p_assurance_package_id
      and p.critical_failures_open = 0
      and p.blocking_threshold_failures = 0
      and p.unresolved_high_risks = 0
      and ep.status = 'approved'
      and d.deployment_status in ('planned', 'active')
      and (
        ep.independent_validation_required = false
        or p.independent_validation_id is not null
      )
      and not exists (
        select 1
        from public.ai_system_suspensions s
        where s.use_case_id = p.use_case_id
          and s.status = 'active'
      )
  );
$$;


