CREATE TABLE IF NOT EXISTS "public"."document_analysis_jobs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "job_type" "text" NOT NULL,
    "document_id" "uuid",
    "comparison_id" "uuid",
    "user_id" "uuid" NOT NULL,
    "payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "status" "text" DEFAULT 'queued'::"text" NOT NULL,
    "attempts" integer DEFAULT 0 NOT NULL,
    "max_attempts" integer DEFAULT 3 NOT NULL,
    "available_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "claimed_at" timestamp with time zone,
    "claimed_by" "text",
    "completed_at" timestamp with time zone,
    "last_error" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "document_analysis_jobs_job_type_check" CHECK (("job_type" = ANY (ARRAY['document_analysis'::"text", 'document_comparison'::"text"]))),
    CONSTRAINT "document_analysis_jobs_max_attempts_check" CHECK ((("max_attempts" >= 1) AND ("max_attempts" <= 10))),
    CONSTRAINT "document_analysis_jobs_status_check" CHECK (("status" = ANY (ARRAY['queued'::"text", 'processing'::"text", 'completed'::"text", 'failed'::"text"]))),
    CONSTRAINT "document_analysis_jobs_target_check" CHECK (((("job_type" = 'document_analysis'::"text") AND ("document_id" IS NOT NULL) AND ("comparison_id" IS NULL)) OR (("job_type" = 'document_comparison'::"text") AND ("comparison_id" IS NOT NULL) AND ("document_id" IS NULL))))
);


ALTER TABLE "public"."document_analysis_jobs" OWNER TO "postgres";


COMMENT ON TABLE "public"."document_analysis_jobs" IS 'Service-role-only durable queue for document analysis and comparison work.';



CREATE OR REPLACE FUNCTION "public"."claim_document_analysis_jobs"("p_worker_id" "text", "p_limit" integer DEFAULT 1) RETURNS SETOF "public"."document_analysis_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  return query
  with candidates as (
    select j.id from public.document_analysis_jobs j
    where j.status = 'queued' and j.available_at <= now() and j.attempts < j.max_attempts
    order by j.created_at for update skip locked
    limit greatest(1, least(coalesce(p_limit, 1), 10))
  ), updated as (
    update public.document_analysis_jobs j
    set status='processing', attempts=j.attempts+1, claimed_at=now(), claimed_by=p_worker_id
    from candidates c where j.id=c.id returning j.*
  ) select * from updated;
end;
$$;


ALTER FUNCTION "public"."claim_document_analysis_jobs"("p_worker_id" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_referral_needs_follow_up"("p_referral_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.community_service_referrals r
    where r.id = p_referral_id
      and r.referral_status not in ('closed', 'cancelled')
      and (
        r.first_access_confirmed_at is null
        or exists (
          select 1 from public.community_referral_barriers b
          where b.community_service_referral_id = r.id
            and b.barrier_status in ('open', 'unresolved')
        )
        or exists (
          select 1 from public.community_referral_waitlist_records w
          where w.community_service_referral_id = r.id
            and w.waitlist_status = 'waiting'
            and (w.last_checked_at is null or w.last_checked_at < now() - interval '14 days')
        )
      )
  );
$$;


ALTER FUNCTION "public"."community_referral_needs_follow_up"("p_referral_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_case_intake"("target_case_id" "uuid", "target_assessment_id" "uuid", "intake_answers" "jsonb", "completed_section_count" integer, "total_section_count" integer) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  intake_id uuid;
  needs_review boolean := false;
begin
  if actor_id is null then
    raise exception 'Authentication required';
  end if;
  if not public.user_has_case_role(
    target_case_id,
    array['case_owner','parent']::text[]
  ) then
    raise exception 'Active parent case membership required';
  end if;
  if completed_section_count < total_section_count or total_section_count <= 0 then
    raise exception 'Every required intake section must be complete';
  end if;
  if not public.profile_ready_for_program(actor_id) then
    raise exception 'Required profile setup is incomplete';
  end if;
  if not public.case_setup_ready_for_program(target_case_id) then
    raise exception 'Required case setup is incomplete';
  end if;

  select coalesce(ppr.requires_worker_review, false)
  into needs_review
  from public.reunification_cases rc
  left join public.program_pathway_rules ppr
    on ppr.intake_stream_label = rc.program_stream
  where rc.id = target_case_id;

  insert into public.assessment_responses(assessment_id, user_id, responses)
  values (
    target_assessment_id,
    actor_id,
    jsonb_build_object(
      'assessmentType', 'intake',
      'completedSections', completed_section_count,
      'answers', intake_answers,
      'intakeComplete', true,
      'completedAt', now()
    )
  );

  insert into public.case_intake_status(
    case_id,
    parent_user_id,
    completed_sections,
    total_sections,
    completed_at,
    reviewer_state,
    updated_at
  )
  values (
    target_case_id,
    actor_id,
    completed_section_count,
    total_section_count,
    now(),
    case when needs_review then 'pending' else 'not_required' end,
    now()
  )
  on conflict (case_id, parent_user_id) do update
  set completed_sections = excluded.completed_sections,
      total_sections = excluded.total_sections,
      completed_at = excluded.completed_at,
      reviewer_state = case when needs_review then 'pending' else 'not_required' end,
      reviewer_user_id = null,
      reviewer_notes = null,
      reviewed_at = null,
      updated_at = now()
  returning id into intake_id;

  return intake_id;
end;
$$;


ALTER FUNCTION "public"."complete_case_intake"("target_case_id" "uuid", "target_assessment_id" "uuid", "intake_answers" "jsonb", "completed_section_count" integer, "total_section_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_parent_intake"("target_case_id" "uuid") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  completed_time timestamptz := now();
  saved_keys text[];
  needs_review boolean := false;
begin
  if actor_id is null then
    raise exception 'Authentication required';
  end if;

  if not exists (
    select 1
    from public.case_memberships cm
    where cm.case_id = target_case_id
      and cm.user_id = actor_id
      and cm.status = 'active'
      and cm.membership_role in ('case_owner', 'parent')
  ) then
    raise exception 'Active parent case membership required';
  end if;

  select completed_section_keys
  into saved_keys
  from public.case_intake_status
  where case_id = target_case_id
    and parent_user_id = actor_id
  for update;

  if not found or cardinality(saved_keys) <> 12 then
    raise exception 'Complete every required intake section before continuing';
  end if;

  if not public.profile_ready_for_program(actor_id) then
    raise exception 'Required parent profile details are incomplete';
  end if;

  if not public.case_setup_ready_for_program(target_case_id) then
    raise exception 'Required family and case details are incomplete';
  end if;

  select exists (
    select 1
    from public.program_pathway_rules ppr
    join public.reunification_cases rc
      on rc.id = target_case_id
     and ppr.program_id = rc.program_stream
    where ppr.requires_worker_review
  )
  into needs_review;

  update public.case_intake_status
  set completed_sections = 12,
      total_sections = 12,
      completed_at = completed_time,
      current_section = 'review',
      reviewer_state = case when needs_review then 'pending' else 'not_required' end,
      reviewer_user_id = null,
      reviewer_notes = null,
      reviewed_at = null,
      last_saved_at = completed_time,
      updated_at = completed_time
  where case_id = target_case_id
    and parent_user_id = actor_id;

  update public.profiles
  set onboarding_status = 'onboarding_complete',
      updated_at = completed_time
  where id = actor_id;

  return completed_time;
end;
$$;


ALTER FUNCTION "public"."complete_parent_intake"("target_case_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."program_recommendations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "case_id" "uuid" NOT NULL,
    "parent_user_id" "uuid" NOT NULL,
    "program_id" "text" NOT NULL,
    "source_stream" "text" NOT NULL,
    "status" "text" DEFAULT 'confirmed'::"text" NOT NULL,
    "confirmed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "program_recommendations_status_check" CHECK (("status" = 'confirmed'::"text"))
);


ALTER TABLE "public"."program_recommendations" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_program_recommendation"("target_case_id" "uuid", "target_program_id" "text") RETURNS "public"."program_recommendations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  selected_stream text;
  recommended_program_id text;
  intake_record public.case_intake_status%rowtype;
  recommendation public.program_recommendations%rowtype;
begin
  if actor_id is null then
    raise exception 'Authentication required';
  end if;
  if not public.user_has_case_role(
    target_case_id,
    array['case_owner','parent']::text[]
  ) then
    raise exception 'Active parent case membership required';
  end if;

  select rc.program_stream
  into selected_stream
  from public.reunification_cases rc
  where rc.id = target_case_id;

  select ppr.program_id
  into recommended_program_id
  from public.program_pathway_rules ppr
  where ppr.intake_stream_label = selected_stream;

  if recommended_program_id is null then
    raise exception 'Saved intake pathway does not map to an available program';
  end if;
  if target_program_id <> recommended_program_id then
    raise exception 'Only the program matching the saved intake pathway can be confirmed';
  end if;

  select *
  into intake_record
  from public.case_intake_status cis
  where cis.case_id = target_case_id
    and cis.parent_user_id = actor_id;

  if intake_record.id is null
    or intake_record.completed_at is null
    or intake_record.completed_sections < intake_record.total_sections then
    raise exception 'Completed intake required before program confirmation';
  end if;

  insert into public.program_recommendations(
    case_id,
    parent_user_id,
    program_id,
    source_stream,
    status,
    confirmed_at
  )
  values (
    target_case_id,
    actor_id,
    recommended_program_id,
    selected_stream,
    'confirmed',
    now()
  )
  on conflict (case_id, parent_user_id) do update
  set program_id = excluded.program_id,
      source_stream = excluded.source_stream,
      status = 'confirmed',
      confirmed_at = now()
  returning * into recommendation;

  return recommendation;
end;
$$;


ALTER FUNCTION "public"."confirm_program_recommendation"("target_case_id" "uuid", "target_program_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."consume_case_report_delivery"("p_token" "text", "p_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c public.case_report_delivery_challenges%rowtype;
  rel public.case_report_release_events%rowtype;
  rf public.report_rendered_files%rowtype;
  outcome text;
begin
  select * into c
  from public.case_report_delivery_challenges
  where token_hash = pg_catalog.encode(
    extensions.digest(coalesce(p_token, ''), 'sha256'),
    'hex'
  )
  for update;

  if c.id is null then
    return pg_catalog.jsonb_build_object('allowed', false);
  end if;

  if c.revoked_at is not null then
    outcome := 'revoked';
  elsif c.disabled_at is not null then
    outcome := 'disabled';
  elsif c.expires_at <= pg_catalog.now() then
    outcome := 'expired';
  elsif c.download_count >= c.max_downloads then
    outcome := 'limit_reached';
  elsif c.code_hash <> pg_catalog.encode(
    extensions.digest(coalesce(p_code, ''), 'sha256'),
    'hex'
  ) then
    update public.case_report_delivery_challenges
    set failed_attempts = least(5, failed_attempts + 1),
        disabled_at = case when failed_attempts + 1 >= 5 then pg_catalog.now() else disabled_at end
    where id = c.id;
    outcome := case when c.failed_attempts + 1 >= 5 then 'disabled' else 'code_failed' end;
  else
    select * into rel
    from public.case_report_release_events
    where id = c.release_event_id;

    if rel.id is null then
      outcome := 'unavailable';
    elsif exists (
      select 1
      from public.report_withdrawals w
      where w.report_id = rel.report_id
        and w.report_version = rel.report_version
    ) then
      outcome := 'withdrawn';
    else
      select * into rf
      from public.report_rendered_files
      where id = rel.rendered_file_id;
      outcome := case
        when rf.id is null or rf.storage_bucket is null or rf.storage_path is null then 'unavailable'
        else 'allowed'
      end;
    end if;
  end if;

  insert into public.case_report_delivery_attempts(challenge_id, outcome)
  values (c.id, outcome);

  if outcome <> 'allowed' then
    return pg_catalog.jsonb_build_object('allowed', false);
  end if;

  update public.case_report_delivery_challenges
  set download_count = download_count + 1
  where id = c.id;

  return pg_catalog.jsonb_build_object(
    'allowed', true,
    'bucket', rf.storage_bucket,
    'path', rf.storage_path,
    'fileSha256', rf.file_hash_sha256,
    'reportVersion', rel.report_version,
    'expiresIn', 600
  );
end;
$$;


ALTER FUNCTION "public"."consume_case_report_delivery"("p_token" "text", "p_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."consume_case_report_delivery"("p_token" "text", "p_code" "text") IS 'Restricted staging verification RPC. Execution is limited to service_role pending public payload review.';



CREATE OR REPLACE FUNCTION "public"."create_family_group"("p_tenant_id" "uuid", "p_family_display_name" "text", "p_primary_adult" "jsonb", "p_children" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_family_id uuid;
  v_adult_member_id uuid;
  v_child jsonb;
  v_child_member_id uuid;
begin
  if not (
    public.has_role(p_tenant_id, 'family_intake_worker')
    or public.has_role(p_tenant_id, 'tenant_administrator')
  ) then
    raise exception 'Not authorised';
  end if;

  insert into public.families (
    tenant_id,
    family_reference,
    family_display_name,
    family_type,
    family_status,
    created_by_user_id
  )
  values (
    p_tenant_id,
    public.generate_family_reference(),
    p_family_display_name,
    'household',
    'active',
    auth.uid()
  )
  returning id into v_family_id;

  insert into public.family_members (
    tenant_id,
    family_id,
    member_reference,
    member_type,
    legal_first_name,
    legal_last_name,
    preferred_name,
    display_name,
    date_of_birth
  )
  values (
    p_tenant_id,
    v_family_id,
    public.generate_family_member_reference(),
    'parent',
    p_primary_adult ->> 'first_name',
    p_primary_adult ->> 'last_name',
    p_primary_adult ->> 'preferred_name',
    coalesce(p_primary_adult ->> 'display_name', trim(concat_ws(' ', p_primary_adult ->> 'first_name', p_primary_adult ->> 'last_name'))),
    nullif(p_primary_adult ->> 'date_of_birth', '')::date
  )
  returning id into v_adult_member_id;

  insert into public.adult_participants (
    tenant_id,
    family_member_id,
    adult_reference,
    participant_category
  )
  values (
    p_tenant_id,
    v_adult_member_id,
    public.generate_adult_reference(),
    'parent'
  );

  for v_child in select value from jsonb_array_elements(p_children)
  loop
    insert into public.family_members (
      tenant_id,
      family_id,
      member_reference,
      member_type,
      legal_first_name,
      legal_last_name,
      preferred_name,
      display_name,
      date_of_birth
    )
    values (
      p_tenant_id,
      v_family_id,
      public.generate_family_member_reference(),
      'child',
      v_child ->> 'first_name',
      v_child ->> 'last_name',
      v_child ->> 'preferred_name',
      coalesce(v_child ->> 'display_name', trim(concat_ws(' ', v_child ->> 'first_name', v_child ->> 'last_name'))),
      nullif(v_child ->> 'date_of_birth', '')::date
    )
    returning id into v_child_member_id;

    insert into public.children (
      tenant_id,
      family_member_id,
      child_reference,
      developmental_stage
    )
    values (
      p_tenant_id,
      v_child_member_id,
      public.generate_child_reference(),
      public.calculate_developmental_stage(nullif(v_child ->> 'date_of_birth', '')::date)
    );

    insert into public.family_relationships (
      tenant_id,
      family_id,
      from_family_member_id,
      to_family_member_id,
      relationship_type,
      biological_relationship,
      relationship_status,
      confidence_level
    )
    values (
      p_tenant_id,
      v_family_id,
      v_adult_member_id,
      v_child_member_id,
      'biological_parent',
      null,
      'reported',
      'reported'
    );
  end loop;

  return v_family_id;
end;
$$;


ALTER FUNCTION "public"."create_family_group"("p_tenant_id" "uuid", "p_family_display_name" "text", "p_primary_adult" "jsonb", "p_children" "jsonb") OWNER TO "postgres";


