CREATE OR REPLACE FUNCTION "public"."get_child_case_share_context"("target_child_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS TABLE("case_id" "uuid", "parent_user_id" "uuid", "caseworker_user_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    cp.case_id,
    rc.parent_user_id,
    coalesce(cp.caseworker_user_id, rc.worker_user_id) as caseworker_user_id
  from public.child_profiles cp
  left join public.reunification_cases rc on rc.id = cp.case_id
  where cp.child_user_id = target_child_user_id
    and cp.case_id is not null
    and (
      target_child_user_id = auth.uid()
      or public.user_has_case_role(
        cp.case_id,
        array['caseworker','supervisor','clinician','admin','super_admin']::text[]
      )
    )
  limit 1;
$$;


ALTER FUNCTION "public"."get_child_case_share_context"("target_child_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_case_access_grant"("target_case_id" "uuid") RETURNS TABLE("membership_role" "text", "case_status" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select cm.membership_role, rc.status
  from public.case_memberships cm
  join public.reunification_cases rc on rc.id = cm.case_id
  where cm.case_id = target_case_id
    and cm.user_id = auth.uid()
    and cm.status = 'active'
  order by case cm.membership_role
    when 'admin' then 1 when 'supervisor' then 2 when 'clinician' then 3
    when 'caseworker' then 4 when 'facilitator' then 5 when 'court_viewer' then 6
    when 'advocate' then 7 when 'carer' then 8 when 'case_owner' then 9
    when 'parent' then 10 else 11 end
  limit 1;
$$;


ALTER FUNCTION "public"."get_my_case_access_grant"("target_case_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_auth_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  insert into public.profiles (
    id,
    display_name,
    preferred_name,
    primary_email,
    created_at,
    updated_at
  )
  values (
    new.id,
    coalesce(new.raw_user_meta_data ->> 'display_name', new.raw_user_meta_data ->> 'full_name'),
    new.raw_user_meta_data ->> 'preferred_name',
    new.email,
    now(),
    now()
  )
  on conflict (id) do nothing;

  return new;
end;
$$;


ALTER FUNCTION "public"."handle_new_auth_user"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'auth'
    AS $$
begin
  insert into public.profiles (id, email)
  values (new.id, new.email)
  on conflict (id) do update
  set
    email = excluded.email,
    updated_at = now();

  insert into public.users (auth_user_id, role)
  values (new.id, 'parent')
  on conflict (auth_user_id) do update
  set role = public.users.role;

  return new;
exception when others then
  raise log 'SafeSteps handle_new_user failed for %: %', new.id, sqlerrm;
  return new;
end;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_active_video_report_authority"("target_parent_user_id" "uuid", "target_user_id" "uuid", "requested_scope" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    target_user_id = (select auth.uid())
    and exists (
      select 1
      from public.video_report_access_authorities authority
      where authority.parent_user_id = target_parent_user_id
        and authority.authorised_user_id = target_user_id
        and authority.active = true
        and authority.starts_at <= pg_catalog.now()
        and (authority.expires_at is null or authority.expires_at > pg_catalog.now())
        and (
          authority.access_scope = requested_scope
          or authority.access_scope = 'video_progress_and_evidence'
        )
    );
$$;


