CREATE OR REPLACE FUNCTION "public"."has_case_access"("p_case_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.cases c
    where c.id = p_case_id
      and (
        public.has_permission(c.tenant_id, 'case.view')
        or public.is_case_worker(c.id)
        or public.is_case_supervisor(c.id)
        or public.is_case_team_member(c.id)
        or public.is_family_member(c.family_id)
      )
  );
$$;


ALTER FUNCTION "public"."has_case_access"("p_case_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_case_permission"("p_user_id" "uuid", "p_case_id" "uuid", "p_permission_code" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
select p_user_id is not null and p_user_id=auth.uid() and (
 exists(select 1 from public.case_participants cp join public.cases c on c.id=cp.case_id
 join public.user_role_assignments ura on ura.user_id=cp.user_id and (ura.case_id=cp.case_id or ura.organisation_id=c.organisation_id)
 join public.role_permissions rp on rp.role_id=ura.role_id join public.security_permissions p on p.id=rp.permission_id
 where cp.case_id=p_case_id and cp.user_id=p_user_id and cp.status='active' and ura.status='active'
 and p.permission_code=p_permission_code and (cp.effective_to is null or cp.effective_to>now())
 and (ura.starts_at is null or ura.starts_at<=now()) and (ura.ends_at is null or ura.ends_at>now())
 and (c.organisation_id is null or public.safesteps_is_active_member(p_user_id,c.organisation_id)))
 or exists(select 1 from public.temporary_access_grants tag where tag.user_id=p_user_id and tag.case_id=p_case_id
 and p_permission_code=any(tag.permission_codes) and tag.revoked_at is null and tag.starts_at<=now() and tag.expires_at>now())
); $$;


ALTER FUNCTION "public"."has_case_permission"("p_user_id" "uuid", "p_case_id" "uuid", "p_permission_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_evidence_access"("p_evidence_record_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.evidence_records er
    where er.id = p_evidence_record_id
      and er.deleted = false
      and (
        public.has_permission(er.tenant_id, 'evidence.view')
        or (er.case_id is not null and public.has_case_access(er.case_id))
        or er.uploader_user_id = auth.uid()
        or exists (
          select 1
          from public.evidence_sharing_grants g
          where g.evidence_record_id = er.id
            and g.revoked_at is null
            and (g.expires_at is null or g.expires_at > now())
            and (
              g.grantee_user_id = auth.uid()
              or g.grantee_family_member_id in (select public.current_family_member_ids())
            )
        )
      )
  );
$$;


ALTER FUNCTION "public"."has_evidence_access"("p_evidence_record_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_permission"("p_tenant_id" "uuid", "p_permission_code" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.role_assignments ra
    join public.role_permissions rp on rp.role_definition_id = ra.role_definition_id
    join public.permission_definitions pd on pd.id = rp.permission_definition_id
    where ra.tenant_id = p_tenant_id
      and ra.user_id = auth.uid()
      and ra.assignment_status = 'active'
      and pd.permission_code = p_permission_code
      and pd.lifecycle_status = 'active'
      and ra.effective_from <= now()
      and (ra.effective_to is null or ra.effective_to > now())
  );
$$;


