    SET "search_path" TO ''
    AS $$
begin raise exception 'Media evidence history is append-only'; end;
$$;


ALTER FUNCTION "public"."media_reject_mutation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."media_require_file_mime"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $_$
begin
  if new.mime_type is null or new.mime_type !~ '^[A-Za-z0-9!#$&^_.+-]+/[A-Za-z0-9!#$&^_.+-]+$'
      or length(new.mime_type) > 127 then raise exception 'New media files require a valid MIME type'; end if;
  return new;
end;
$_$;


ALTER FUNCTION "public"."media_require_file_mime"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."media_seal_custody"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare prior public.evidence_custody_events;
begin
  perform 1 from public.media_evidence where id = new.evidence_id for update;
  select * into prior from public.evidence_custody_events where evidence_id = new.evidence_id order by sequence desc limit 1;
  new.sequence := coalesce(prior.sequence,0) + 1;
  new.previous_hash := coalesce(prior.event_hash,repeat('0',64));
  new.created_at := clock_timestamp();
  new.envelope := jsonb_build_object('version',2,'evidenceId',new.evidence_id,'sequence',new.sequence,
    'actorId',new.actor_id,'actorRole',new.actor_role,'sourceIp',new.source_ip,'deviceInformation',new.device_information,
    'action',new.action,'requestId',new.request_id,'payload',new.payload,
    'previousHash',new.previous_hash,'createdAt',new.created_at);
  new.event_hash := encode(sha256(convert_to(new.envelope::text,'UTF8')),'hex');
  return new;
end;
$$;


ALTER FUNCTION "public"."media_seal_custody"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."persist_personal_ai_chat_turn"("p_user_id" "uuid", "p_conversation_id" "uuid", "p_user_message" "text", "p_assistant_message" "text", "p_flow_id" "text", "p_state" "text", "p_risk_level" "text", "p_intent_label" "text", "p_routing_confidence" numeric, "p_escalation_type" "text", "p_signal_ids" "text"[], "p_completion_state" "text", "p_store_conversation" boolean, "p_store_note" boolean, "p_request_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_conversation_id uuid;
  v_user_message_id uuid;
  v_assistant_message_id uuid;
  v_note_id uuid;
  v_safety_event_id uuid;
  v_user_content text;
begin
  if p_user_id is null then raise exception 'User is required'; end if;
  if p_risk_level not in ('low','medium','high','critical') then raise exception 'Invalid risk level'; end if;
  if p_state not in ('start','reflect','clarify','safety_check','support','escalate','document','close') then raise exception 'Invalid state'; end if;
  if not p_store_conversation then
    return jsonb_build_object('stored',false,'conversationId',null);
  end if;
  if char_length(coalesce(p_user_message,'')) not between 1 and 1200 or char_length(coalesce(p_assistant_message,'')) not between 1 and 2000 then raise exception 'Invalid message length'; end if;

  if not exists(select 1 from public.personal_ai_consents where user_id=p_user_id and purpose='conversation_storage' and revoked_at is null and (expires_at is null or expires_at>now())) then
    insert into public.personal_ai_consents(user_id,purpose,policy_version) values(p_user_id,'conversation_storage','1.0');
  end if;

  if p_conversation_id is null then
    insert into public.personal_ai_conversations(user_id,current_flow_id,current_state,risk_level,status,title)
    values(p_user_id,p_flow_id,p_state,p_risk_level,case when p_risk_level='critical' then 'escalated' else 'active' end,'SafeSteps Personal AI Support')
    returning id into v_conversation_id;
  else
    select id into v_conversation_id from public.personal_ai_conversations where id=p_conversation_id and user_id=p_user_id for update;
    if v_conversation_id is null then raise exception 'Conversation not found or not owned by user'; end if;
    update public.personal_ai_conversations set current_flow_id=p_flow_id,current_state=p_state,risk_level=p_risk_level,status=case when p_risk_level='critical' then 'escalated' else status end,updated_at=now() where id=v_conversation_id;
  end if;

  v_user_content := case when p_risk_level in ('high','critical') then '[Safety-sensitive disclosure withheld from ordinary message storage]' else p_user_message end;
  insert into public.personal_ai_messages(conversation_id,sender,content,risk_level,intent_label,routing_confidence)
  values(v_conversation_id,'user',v_user_content,p_risk_level,p_intent_label,p_routing_confidence) returning id into v_user_message_id;
  insert into public.personal_ai_messages(conversation_id,sender,content,risk_level,intent_label,routing_confidence)
  values(v_conversation_id,'assistant',p_assistant_message,p_risk_level,p_intent_label,p_routing_confidence) returning id into v_assistant_message_id;

  if p_store_note then
    insert into public.personal_ai_interaction_notes(conversation_id,flow_id,risk_level,safety_check_result,actions_taken,resources_offered,escalation_status,completion_state)
    values(v_conversation_id,p_flow_id,p_risk_level,case when p_risk_level='critical' then 'Immediate safety check shown' else null end,
      case when p_risk_level in ('high','critical') then array['Minimum-necessary safety guidance shown'] else array['Support response shown'] end,
      case when p_risk_level='critical' then array['Real-world urgent support'] else '{}'
      end,p_escalation_type,p_completion_state) returning id into v_note_id;
  end if;

  if p_risk_level in ('high','critical') then
    insert into public.personal_ai_safety_events(conversation_id,risk_level,escalation_type,immediate_risk,signal_ids,action_shown,human_handoff_offered)
    values(v_conversation_id,p_risk_level,p_escalation_type,p_risk_level='critical',coalesce(p_signal_ids,'{}'),left(p_assistant_message,1000),true)
    returning id into v_safety_event_id;
  end if;

  insert into public.personal_ai_audit_logs(user_id,actor_id,action,target_type,target_id,metadata)
  values(p_user_id,p_user_id,'chat_turn_persisted','personal_ai_conversation',v_conversation_id,
    jsonb_build_object('requestId',p_request_id,'riskLevel',p_risk_level,'flowId',p_flow_id,'userMessageRedacted',p_risk_level in ('high','critical'),'noteCreated',v_note_id is not null,'safetyEventCreated',v_safety_event_id is not null));

  return jsonb_build_object('stored',true,'conversationId',v_conversation_id,'userMessageId',v_user_message_id,'assistantMessageId',v_assistant_message_id,'noteId',v_note_id,'safetyEventId',v_safety_event_id);
end;
$$;


ALTER FUNCTION "public"."persist_personal_ai_chat_turn"("p_user_id" "uuid", "p_conversation_id" "uuid", "p_user_message" "text", "p_assistant_message" "text", "p_flow_id" "text", "p_state" "text", "p_risk_level" "text", "p_intent_label" "text", "p_routing_confidence" numeric, "p_escalation_type" "text", "p_signal_ids" "text"[], "p_completion_state" "text", "p_store_conversation" boolean, "p_store_note" boolean, "p_request_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."persist_personal_ai_chat_turn"("p_user_id" "uuid", "p_conversation_id" "uuid", "p_user_message" "text", "p_assistant_message" "text", "p_flow_id" "text", "p_state" "text", "p_risk_level" "text", "p_intent_label" "text", "p_routing_confidence" numeric, "p_escalation_type" "text", "p_signal_ids" "text"[], "p_completion_state" "text", "p_store_conversation" boolean, "p_store_note" boolean, "p_request_id" "text") IS 'Backend-only atomic persistence. High/critical user disclosures are replaced with a non-verbatim marker before storage.';



CREATE OR REPLACE FUNCTION "public"."prepare_case_report_delivery"("p_case_id" "uuid", "p_release_event_id" "uuid", "p_recipient_id" "uuid", "p_expires_minutes" integer DEFAULT 60, "p_max_downloads" integer DEFAULT 1) RETURNS TABLE("challenge_id" "uuid", "delivery_token" "text", "verification_code" "text", "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
 rel public.case_report_release_events%rowtype;
 rec public.report_recipients%rowtype;
 raw_token text;
 raw_code text;
 random_value bigint;
begin
 if p_expires_minutes<5 or p_expires_minutes>1440 then raise exception 'Challenge expiry must be 5 minutes to 24 hours'; end if;
 if p_max_downloads<1 or p_max_downloads>10 then raise exception 'Download limit must be 1 to 10'; end if;
 if not public.user_has_active_case_membership(p_case_id)
  or not public.user_has_case_role(p_case_id,array['supervisor','admin']::text[]) then
  raise exception 'Report delivery preparation denied';
 end if;
 select * into rel from public.case_report_release_events where id=p_release_event_id and case_id=p_case_id;
 select * into rec from public.report_recipients where id=p_recipient_id and report_id=rel.report_id
  and report_version=rel.report_version and released_at is not null and revoked_at is null
  and (access_expires_at is null or access_expires_at>now());
 if rel.id is null or rec.id is null then raise exception 'Active released recipient record required'; end if;
 raw_token:=encode(extensions.gen_random_bytes(24),'hex');
 loop
  random_value:=('x'||encode(extensions.gen_random_bytes(4),'hex'))::bit(32)::bigint;
  exit when random_value<4294000000;
 end loop;
 raw_code:=lpad((random_value%1000000)::text,6,'0');
 return query insert into public.case_report_delivery_challenges(
  case_id,release_event_id,recipient_id,token_hash,code_hash,expires_at,max_downloads,created_by
 ) values(p_case_id,rel.id,rec.id,encode(extensions.digest(raw_token,'sha256'),'hex'),
  encode(extensions.digest(raw_code,'sha256'),'hex'),now()+make_interval(mins=>p_expires_minutes),
  p_max_downloads,(select auth.uid()))
 returning id,raw_token,raw_code,case_report_delivery_challenges.expires_at;
end $$;


ALTER FUNCTION "public"."prepare_case_report_delivery"("p_case_id" "uuid", "p_release_event_id" "uuid", "p_recipient_id" "uuid", "p_expires_minutes" integer, "p_max_downloads" integer) OWNER TO "postgres";


