    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if old.child_words_exact is distinct from new.child_words_exact then
    raise exception 'Child disclosure exact wording cannot be overwritten';
  end if;
  return new;
end;
$$;


