CREATE OR REPLACE FUNCTION "public"."release_case_report_version"("p_case_id" "uuid", "p_report_id" "uuid", "p_report_version_id" "uuid", "p_rendered_file_id" "uuid", "p_release_notes" "text" DEFAULT ''::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $_$
declare
  target_report public.reports%rowtype;
  target_version public.report_versions%rowtype;
  target_file public.report_rendered_files%rowtype;
  target_approval public.report_approvals%rowtype;
  release_id uuid;
  release_code text;
begin
  if not public.user_has_active_case_membership(p_case_id)
    or not public.user_has_case_role(p_case_id, array['supervisor','admin']::text[]) then
    raise exception 'SafeSteps report release access denied';
  end if;

  select * into target_report
  from public.reports
  where id = p_report_id and reunification_case_id = p_case_id
  for update;

  select * into target_version
  from public.report_versions
  where id = p_report_version_id
    and report_id = p_report_id
    and version_number = target_report.current_version
  for update;

  if target_report.id is null or target_version.id is null then
    raise exception 'Current report version not found for the selected case';
  end if;

  if target_report.status <> 'approved' or target_version.version_status <> 'approved' then
    raise exception 'Only an independently approved current version can be released';
  end if;

  select * into target_approval
  from public.report_approvals
  where report_id = p_report_id
    and report_version = target_version.version_number
    and decision = 'approved'
    and independence_confirmed is true
    and conflict_confirmed_clear is true
  order by approved_at desc
  limit 1;

  if target_approval.id is null then
    raise exception 'Independent approval history is missing';
  end if;

  select * into target_file
  from public.report_rendered_files
  where id = p_rendered_file_id
    and report_id = p_report_id
    and report_version = target_version.version_number
    and lower(file_format) = 'pdf';

  if target_file.id is null then
    raise exception 'A traceable PDF for the approved version is required';
  end if;

  if target_version.content_hash !~ '^[0-9a-fA-F]{64}$'
    or target_file.file_hash_sha256 !~ '^[0-9a-fA-F]{64}$' then
    raise exception 'Snapshot and PDF SHA-256 hashes are required before release';
  end if;

  release_code := upper(encode(gen_random_bytes(8), 'hex'));

  insert into public.case_report_release_events (
    case_id, report_id, report_version_id, report_version, approval_id,
    rendered_file_id, content_hash_sha256, file_hash_sha256,
    verification_code, watermark_text, release_notes, released_by
  ) values (
    p_case_id, p_report_id, target_version.id, target_version.version_number,
    target_approval.id, target_file.id, lower(target_version.content_hash),
    lower(target_file.file_hash_sha256), release_code,
    'SafeSteps • ' || target_report.report_reference || ' • v' || target_version.version_number
      || ' • ' || release_code,
    trim(coalesce(p_release_notes, '')), (select auth.uid())
  )
  returning id into release_id;

  update public.report_versions
  set version_status = 'released', released_at = now()
  where id = target_version.id;

  update public.reports
  set status = 'released', released_at = now(), record_version = record_version + 1
  where id = target_report.id;

  return release_id;
end;
$_$;


ALTER FUNCTION "public"."release_case_report_version"("p_case_id" "uuid", "p_report_id" "uuid", "p_report_version_id" "uuid", "p_rendered_file_id" "uuid", "p_release_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_case_report_correction"("p_case_id" "uuid", "p_report_id" "uuid", "p_correction_type" "text", "p_description" "text", "p_material_change" boolean) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare r public.reports%rowtype; correction_id uuid;
begin
 if length(trim(coalesce(p_description,'')))=0 then raise exception 'Correction details are required'; end if;
 if not public.user_has_active_case_membership(p_case_id)
  or not public.user_has_case_role(p_case_id,array['caseworker','supervisor','admin']::text[]) then
  raise exception 'Report correction access denied';
 end if;
 select * into r from public.reports where id=p_report_id and reunification_case_id=p_case_id;
 if r.id is null or r.status not in ('released','withdrawn','superseded') then
  raise exception 'Corrections apply only to an existing released history';
 end if;
 insert into public.report_corrections(
  report_id,affected_version,correction_type,correction_description,requested_by,status,material_change
 ) values(
  r.id,r.current_version,p_correction_type,trim(p_description),(select auth.uid()),'requested',p_material_change
 ) returning id into correction_id;
 return correction_id;
end $$;


ALTER FUNCTION "public"."request_case_report_correction"("p_case_id" "uuid", "p_report_id" "uuid", "p_correction_type" "text", "p_description" "text", "p_material_change" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_case_report_export"("p_case_id" "uuid", "p_release_event_id" "uuid", "p_recipient_id" "uuid", "p_authority" "text", "p_purpose" "text", "p_expiry_seconds" integer DEFAULT 600) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare rel public.case_report_release_events%rowtype;
 rec public.report_recipients%rowtype;
 event_id uuid;
begin
 if length(trim(coalesce(p_authority,'')))=0 or length(trim(coalesce(p_purpose,'')))=0 then
  raise exception 'Recipient authority and export purpose are required';
 end if;
 if p_expiry_seconds<60 or p_expiry_seconds>600 then
  raise exception 'Sensitive report links must expire within 1 to 10 minutes';
 end if;
 select * into rel from public.case_report_release_events
 where id=p_release_event_id and case_id=p_case_id;
 if rel.id is null then raise exception 'Released report version not found'; end if;
 select * into rec from public.report_recipients
 where id=p_recipient_id and report_id=rel.report_id and report_version=rel.report_version
   and released_at is not null and revoked_at is null
   and (access_expires_at is null or access_expires_at>now())
   and (recipient_user_id=(select auth.uid())
     or public.user_has_case_role(p_case_id,array['supervisor','admin']::text[]));
 if rec.id is null then raise exception 'Recipient is not authorised for this released version'; end if;
 if rec.release_purpose<>p_purpose then raise exception 'Export purpose does not match approved recipient purpose'; end if;
 if exists(select 1 from public.report_withdrawals w
   where w.report_id=rel.report_id and w.report_version=rel.report_version) then
  raise exception 'Withdrawn report versions cannot be exported';
 end if;
 if not public.user_has_active_case_membership(p_case_id) then
  raise exception 'Active case membership is required';
 end if;
 insert into public.case_report_export_events(
  case_id,release_event_id,report_id,report_version,recipient_id,rendered_file_id,
  requested_by,authority,purpose,action,outcome,signed_url_expires_at
 ) values(
  p_case_id,rel.id,rel.report_id,rel.report_version,rec.id,rel.rendered_file_id,
  (select auth.uid()),trim(p_authority),trim(p_purpose),
  'signed_url_requested','allowed',now()+make_interval(secs=>p_expiry_seconds)
 ) returning id into event_id;
 return event_id;
end $$;


ALTER FUNCTION "public"."request_case_report_export"("p_case_id" "uuid", "p_release_event_id" "uuid", "p_recipient_id" "uuid", "p_authority" "text", "p_purpose" "text", "p_expiry_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_case_document_version"("p_case_id" "uuid", "p_document_id" "uuid", "p_document_version_id" "uuid", "p_decision" "text", "p_include_in_report" boolean DEFAULT false, "p_review_notes" "text" DEFAULT ''::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  review_event_id uuid;
  current_document_id uuid;
begin
  if p_decision not in ('accepted', 'needs_update', 'excluded') then
    raise exception 'Unsupported evidence review decision';
  end if;

  if p_include_in_report and p_decision <> 'accepted' then
    raise exception 'Only accepted evidence can be selected for report inclusion';
  end if;

  if p_decision in ('needs_update', 'excluded') and length(trim(coalesce(p_review_notes, ''))) = 0 then
    raise exception 'Review notes are required when evidence is returned or excluded';
  end if;

  if not public.user_has_active_case_membership(p_case_id)
    or not public.user_has_case_role(
      p_case_id,
      array['caseworker', 'supervisor', 'admin']::text[]
    ) then
    raise exception 'SafeSteps evidence review access denied';
  end if;

  select document.id
    into current_document_id
  from public.case_documents as document
  join public.case_document_versions as version
    on version.document_id = document.id
  where document.case_id = p_case_id
    and document.id = p_document_id
    and document.current_version_id = p_document_version_id
    and version.id = p_document_version_id
  for update of document, version;

  if current_document_id is null then
    raise exception 'The selected current document version could not be reviewed';
  end if;

  update public.case_document_versions
  set
    review_status = p_decision,
    review_notes = trim(coalesce(p_review_notes, ''))
  where id = p_document_version_id;

  update public.case_documents
  set
    status = p_decision,
    court_report_include = p_include_in_report,
    notes = trim(coalesce(p_review_notes, '')),
    updated_at = now()
  where id = p_document_id
    and case_id = p_case_id;

  insert into public.case_document_review_events (
    case_id,
    document_id,
    document_version_id,
    decision,
    include_in_report,
    review_notes,
    reviewed_by
  )
  values (
    p_case_id,
    p_document_id,
    p_document_version_id,
    p_decision,
    p_include_in_report,
    trim(coalesce(p_review_notes, '')),
    (select auth.uid())
  )
  returning id into review_event_id;

  return review_event_id;
end;
$$;


ALTER FUNCTION "public"."review_case_document_version"("p_case_id" "uuid", "p_document_id" "uuid", "p_document_version_id" "uuid", "p_decision" "text", "p_include_in_report" boolean, "p_review_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_case_intake"("target_case_id" "uuid", "next_reviewer_state" "text", "next_reviewer_notes" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_id uuid := auth.uid();
begin
  if actor_id is null then raise exception 'Authentication required'; end if;
  if next_reviewer_state not in ('approved','changes_required') then
    raise exception 'Invalid reviewer state';
  end if;
  if not public.user_has_case_role(target_case_id, array['caseworker','supervisor','admin']::text[]) then
    raise exception 'Assigned worker, supervisor, or admin review required';
  end if;

  update public.case_intake_status
  set reviewer_state = next_reviewer_state,
      reviewer_user_id = actor_id,
      reviewer_notes = nullif(btrim(coalesce(next_reviewer_notes, '')), ''),
      reviewed_at = now(),
      updated_at = now()
  where case_id = target_case_id and completed_at is not null;

  if not found then raise exception 'Completed intake not found for this case'; end if;
end;
$$;


ALTER FUNCTION "public"."review_case_intake"("target_case_id" "uuid", "next_reviewer_state" "text", "next_reviewer_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revoke_personal_ai_memory_consent"("target_consent_type" "text", "target_policy_version" "text") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare affected integer;
begin
  if target_consent_type not in ('memory','support_plan','sensitive_memory') then raise exception 'Invalid consent type'; end if;
  insert into public.personal_ai_memory_consents(user_id,consent_type,status,policy_version,revoked_at)
    values(auth.uid(),target_consent_type,'revoked',target_policy_version,now());
  update public.personal_ai_family_memory set status='suppressed',updated_at=now()
    where user_id=auth.uid() and consent_type=target_consent_type and status in ('active','pending_review');
  get diagnostics affected = row_count; return affected;
end; $$;


ALTER FUNCTION "public"."revoke_personal_ai_memory_consent"("target_consent_type" "text", "target_policy_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rollback_personal_ai_flow_version"("target_id" "uuid", "rollback_reason" "text") RETURNS "public"."personal_ai_flow_versions"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare withdrawn public.personal_ai_flow_versions; replacement public.personal_ai_flow_versions;
begin
  if not public.current_user_has_role('admin') then raise exception 'Administrator access required'; end if;
  select * into withdrawn from public.personal_ai_flow_versions where id = target_id and status = 'active' for update;
  if not found then raise exception 'Target is not the active version'; end if;
  select * into replacement from public.personal_ai_flow_versions where flow_id = withdrawn.flow_id and id <> withdrawn.id and status in ('deprecated','approved') order by effective_from desc nulls last, created_at desc limit 1 for update;
  if replacement.id is null then raise exception 'No prior approved version is available'; end if;
  update public.personal_ai_flow_versions set status='rolled_back', effective_to=now(), updated_at=now() where id=withdrawn.id;
  update public.personal_ai_flow_versions set status='active', effective_from=now(), effective_to=null, updated_at=now() where id=replacement.id returning * into replacement;
  insert into public.personal_ai_flow_version_audit_logs(flow_version_id,flow_id,previous_version,new_version,action,actor_user_id,reason) values(withdrawn.id,withdrawn.flow_id,withdrawn.version,replacement.version,'rolled_back',auth.uid(),rollback_reason);
  return replacement;
end; $$;


ALTER FUNCTION "public"."rollback_personal_ai_flow_version"("target_id" "uuid", "rollback_reason" "text") OWNER TO "postgres";


