CREATE OR REPLACE FUNCTION "public"."safesteps_can_access_case_v19"("p_user_id" "uuid", "p_case_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select p_user_id = (select auth.uid())
    and exists (
      select 1
      from public.cases c
      where c.id = p_case_id
        and (
          public.safesteps_can_manage_casework(p_user_id, c.organisation_id)
          or c.primary_worker_id = p_user_id
          or exists (
            select 1
            from public.case_allocations_v19 a
            where a.case_id = c.id
              and a.status = 'active'
              and a.allocated_to_user_id = p_user_id
              and (a.effective_to is null or a.effective_to > now())
          )
          or exists (
            select 1
            from public.case_participants cp
            where cp.case_id = c.id
              and cp.user_id = p_user_id
              and cp.status = 'active'
          )
        )
    );
$$;


ALTER FUNCTION "public"."safesteps_can_access_case_v19"("p_user_id" "uuid", "p_case_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."safesteps_can_access_community_referral"("p_user_id" "uuid", "p_referral_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select p_user_id is not null
    and p_user_id = auth.uid()
    and exists (
      select 1
      from public.community_service_referrals r
      where r.id = p_referral_id
        and (
          r.parent_user_id = p_user_id
          or r.referred_by_user_id = p_user_id
          or public.safesteps_can_manage_community_services(p_user_id)
          or (
            r.case_id is not null
            and public.safesteps_can_access_case_v19(p_user_id, r.case_id)
          )
        )
    );
