CREATE OR REPLACE FUNCTION "public"."should_activate_ai_fallback"("p_service_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.ai_current_service_health h
    where h.service_id = p_service_id
      and (h.health_status in ('unavailable', 'failed') or h.failure_rate >= 0.20 or h.saturation_percentage >= 95)
  )
  or exists (
    select 1
    from public.ai_operational_alerts a
    where a.service_id = p_service_id
      and a.status = 'open'
      and a.alert_severity in ('critical', 'emergency')
  );
$$;


ALTER FUNCTION "public"."should_activate_ai_fallback"("p_service_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."should_block_ai_experiment"("p_experiment_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.ai_experiment_protocols e
    where e.id = p_experiment_id
      and (
        e.status not in ('approved', 'running')
        or exists (
          select 1
          from public.ai_experiment_results r
          where r.experiment_id = e.id
            and (r.rollback_triggered = true or r.recommendation in ('pause', 'rollback', 'reject'))
        )
      )
  );
$$;


ALTER FUNCTION "public"."should_block_ai_experiment"("p_experiment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."should_escalate_child_request"("p_request_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.child_support_requests r
    where r.id = p_request_id
      and r.status in ('submitted', 'acknowledged')
      and (
        r.system_safety_priority in ('urgent', 'immediate')
        or r.request_category in ('feel_unsafe', 'need_help_now', 'do_not_want_contact')
      )
  );
$$;


ALTER FUNCTION "public"."should_escalate_child_request"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."should_pause_ai_output_reliance"("p_output_lineage_record_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.ai_contestability_requests cr
    join public.ai_contestability_triage ct on ct.contestability_request_id = cr.id
    where cr.status not in ('resolved', 'closed', 'withdrawn')
      and (
        ct.output_reliance_should_pause = true
        or ct.report_release_should_pause = true
        or ct.automated_workflow_should_suspend = true
      )
      and (
        cr.explanation_id in (
          select e.id
          from public.ai_explanations e
          where e.output_lineage_record_id = p_output_lineage_record_id
        )
      )
  );
$$;


ALTER FUNCTION "public"."should_pause_ai_output_reliance"("p_output_lineage_record_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."program_enrollments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "owner_id" "uuid" NOT NULL,
    "program_id" "text" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone,
    "case_id" "uuid",
    "intake_status_id" "uuid",
    "gate_checked_at" timestamp with time zone,
    CONSTRAINT "program_enrollments_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'paused'::"text", 'completed'::"text"])))
);


ALTER TABLE "public"."program_enrollments" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_program_enrollment"("target_case_id" "uuid", "target_program_id" "text") RETURNS "public"."program_enrollments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_id uuid := auth.uid();
  intake_id uuid;
  enrollment public.program_enrollments%rowtype;
begin
  if actor_id is null then raise exception 'Authentication required'; end if;
  intake_id := public.assert_program_start_gate(target_case_id, actor_id, target_program_id);

  select * into enrollment
  from public.program_enrollments pe
  where pe.owner_id = actor_id and pe.case_id = target_case_id and pe.program_id = target_program_id and pe.status = 'active'
  limit 1;
  if enrollment.id is not null then return enrollment; end if;

  insert into public.program_enrollments(owner_id, case_id, program_id, status, intake_status_id, gate_checked_at)
  values (actor_id, target_case_id, target_program_id, 'active', intake_id, now())
  returning * into enrollment;
  return enrollment;
end;
$$;


ALTER FUNCTION "public"."start_program_enrollment"("target_case_id" "uuid", "target_program_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_evidence_record_legal_hold"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  update public.evidence_records
  set legal_hold = exists (
    select 1
    from public.evidence_legal_holds h
    where h.evidence_record_id = coalesce(new.evidence_record_id, old.evidence_record_id)
      and h.hold_status = 'active'
      and h.released_at is null
  )
  where id = coalesce(new.evidence_record_id, old.evidence_record_id);

  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "public"."sync_evidence_record_legal_hold"() OWNER TO "postgres";


