CREATE OR REPLACE FUNCTION "public"."validate_adult_member_type"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_member_type text;
begin
  select member_type into v_member_type from public.family_members where id = new.family_member_id;
  if v_member_type = 'child' then
    raise exception 'Adult participant cannot link to a child family member';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."validate_adult_member_type"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_case_participant"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_case_tenant uuid;
  v_case_family uuid;
  v_member_tenant uuid;
  v_member_family uuid;
begin
  select tenant_id, family_id into v_case_tenant, v_case_family from public.cases where id = new.case_id;
  select tenant_id, family_id into v_member_tenant, v_member_family from public.family_members where id = new.family_member_id;

  if v_case_tenant is distinct from new.tenant_id or v_member_tenant is distinct from new.tenant_id then
    raise exception 'Case participant tenant mismatch';
  end if;

  if v_case_family is distinct from v_member_family then
    raise exception 'Case participant must belong to the case family';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_case_participant"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_case_tenant_relationships"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_family_tenant uuid;
  v_org_tenant uuid;
begin
  if new.family_id is not null then
    select tenant_id into v_family_tenant from public.families where id = new.family_id;
    if v_family_tenant is distinct from new.tenant_id then
      raise exception 'Family tenant does not match case tenant';
    end if;
  end if;

  if new.organisation_id is not null then
    select tenant_id into v_org_tenant from public.organisations where id = new.organisation_id;
    if v_org_tenant is distinct from new.tenant_id then
      raise exception 'Organisation tenant does not match case tenant';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_case_tenant_relationships"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_child_member_type"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_member_type text;
begin
  select member_type into v_member_type from public.family_members where id = new.family_member_id;
  if v_member_type is distinct from 'child' then
    raise exception 'Child record must link to a child family member';
  end if;
  insert into public.child_privacy_settings (tenant_id, child_id)
  values (new.tenant_id, new.id)
  on conflict (child_id) do nothing;
  return new;
end;
$$;


ALTER FUNCTION "public"."validate_child_member_type"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_family_member_tenant"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_family_tenant_id uuid;
begin
  select tenant_id into v_family_tenant_id from public.families where id = new.family_id;
  if v_family_tenant_id is distinct from new.tenant_id then
    raise exception 'Family member tenant does not match family tenant';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."validate_family_member_tenant"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_family_relationship_tenant"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_from_family uuid;
  v_to_family uuid;
  v_from_tenant uuid;
  v_to_tenant uuid;
begin
  select family_id, tenant_id into v_from_family, v_from_tenant
  from public.family_members where id = new.from_family_member_id;

  select family_id, tenant_id into v_to_family, v_to_tenant
  from public.family_members where id = new.to_family_member_id;

  if v_from_family is distinct from new.family_id or v_to_family is distinct from new.family_id then
    raise exception 'Relationship members must belong to the relationship family';
  end if;

  if v_from_tenant is distinct from new.tenant_id or v_to_tenant is distinct from new.tenant_id then
    raise exception 'Relationship members must belong to the relationship tenant';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_family_relationship_tenant"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_household_membership_family"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_household_family uuid;
  v_member_family uuid;
begin
  select family_id into v_household_family from public.households where id = new.household_id;
  select family_id into v_member_family from public.family_members where id = new.family_member_id;
  if v_household_family is distinct from v_member_family then
    raise exception 'Household member must belong to the same family as the household';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."validate_household_membership_family"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_parent_child_message_case"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not exists (
    select 1 from public.case_memberships cm
    where cm.case_id = new.case_id
      and cm.user_id = new.child_user_id
      and cm.membership_role = 'child'
      and cm.status = 'active'
  ) then
    raise exception 'child is not an active member of the selected case';
  end if;

  if new.parent_user_id is not null and not exists (
    select 1 from public.case_memberships cm
    where cm.case_id = new.case_id
      and cm.user_id = new.parent_user_id
      and cm.membership_role in ('case_owner','parent')
      and cm.status = 'active'
  ) then
    raise exception 'parent is not an active member of the selected case';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_parent_child_message_case"() OWNER TO "postgres";


