CREATE OR REPLACE VIEW "public"."ai_current_service_health" WITH ("security_invoker"='true') AS
 SELECT DISTINCT ON ("service_id", "environment_code", COALESCE("region_code", ''::"text")) "service_id",
    "environment_code",
    "region_code",
    "health_status",
    "health_summary",
    "availability_percentage",
    "latency_p95_ms",
    "failure_rate",
    "saturation_percentage",
