CREATE OR REPLACE VIEW "public"."case_management_work_queue" WITH ("security_invoker"='true') AS
 SELECT "c"."id" AS "case_id",
    "c"."case_reference",
    "c"."organisation_id",
    "c"."status",
    "c"."priority_level",
    "count"(DISTINCT "t"."id") FILTER (WHERE ("t"."status" <> ALL (ARRAY['completed'::"text", 'cancelled'::"text", 'closed'::"text"]))) AS "open_task_count",
    "count"(DISTINCT "t"."id") FILTER (WHERE (("t"."status" <> ALL (ARRAY['completed'::"text", 'cancelled'::"text", 'closed'::"text"])) AND ("t"."due_at" < "now"()))) AS "overdue_task_count",
    "count"(DISTINCT "a"."id") FILTER (WHERE (("a"."appointment_status" = 'scheduled'::"text") AND ("a"."scheduled_start_at" >= "now"()))) AS "upcoming_appointment_count",
    "count"(DISTINCT "d"."id") FILTER (WHERE (("d"."high_impact_decision" = true) AND ("public"."can_finalise_case_decision_v19"("d"."id") = false))) AS "high_impact_decisions_needing_review"
   FROM ((("public"."cases" "c"
     LEFT JOIN "public"."case_tasks" "t" ON (("t"."case_id" = "c"."id")))
     LEFT JOIN "public"."case_appointments" "a" ON (("a"."case_id" = "c"."id")))
     LEFT JOIN "public"."case_decision_records" "d" ON (("d"."case_id" = "c"."id")))
  GROUP BY "c"."id", "c"."case_reference", "c"."organisation_id", "c"."status", "c"."priority_level";


ALTER VIEW "public"."case_management_work_queue" OWNER TO "postgres";


