CREATE OR REPLACE VIEW "public"."case_transfer_readiness_queue" WITH ("security_invoker"='true') AS
 SELECT "id" AS "transfer_id",
    "transfer_reference",
    "case_id",
    "status",
    "family_notified",
    "completed_at",
    "public"."can_transfer_case_v19"("id") AS "ready_to_transfer"
   FROM "public"."case_transfer_records" "t"
  WHERE ("status" = ANY (ARRAY['planned'::"text", 'approved'::"text"]));


