CREATE OR REPLACE VIEW "public"."community_service_directory_view" WITH ("security_invoker"='true') AS
 SELECT "s"."id" AS "community_service_id",
    "s"."service_reference",
    "s"."service_name",
    "s"."service_description",
    "s"."delivery_modes",
    "s"."cost_type",
    "s"."emergency_service",
    "s"."crisis_access_available",
    "c"."category_code",
    "c"."category_name",
    "p"."provider_name",
    "p"."verification_status",
    "latest"."capacity_status",
    "latest"."estimated_wait_days"
   FROM ((("public"."community_services" "s"
     JOIN "public"."community_service_categories" "c" ON (("c"."id" = "s"."service_category_id")))
     JOIN "public"."community_service_providers" "p" ON (("p"."id" = "s"."community_service_provider_id")))
     LEFT JOIN LATERAL ( SELECT "cs"."capacity_status",
            "cs"."estimated_wait_days"
           FROM "public"."community_service_capacity_snapshots" "cs"
          WHERE ("cs"."community_service_id" = "s"."id")
          ORDER BY "cs"."captured_at" DESC
         LIMIT 1) "latest" ON (true))
  WHERE (("s"."service_status" = 'active'::"text") AND ("p"."provider_status" = 'active'::"text"));


