    "notice_version" "text" NOT NULL,
    "purposes" "text"[] NOT NULL,
    "restrictions" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "granted_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "expires_at" timestamp with time zone NOT NULL,
    "supersedes_id" "uuid",
    CONSTRAINT "evidence_consents_authority_reference_check" CHECK ((("length"("authority_reference") >= 1) AND ("length"("authority_reference") <= 500))),
    CONSTRAINT "evidence_consents_authority_type_check" CHECK (("authority_type" = ANY (ARRAY['self'::"text", 'reviewed_representative'::"text", 'reviewed_legal_authority'::"text"]))),
    CONSTRAINT "evidence_consents_check" CHECK (("expires_at" > "granted_at")),
    CONSTRAINT "evidence_consents_purposes_check" CHECK (("purposes" <@ ARRAY['collect'::"text", 'view'::"text", 'review'::"text", 'analyse'::"text", 'export'::"text"]))
);


