CREATE OR REPLACE VIEW "public"."evidence_timeline_view" WITH ("security_invoker"='true') AS
 SELECT "er"."id" AS "evidence_record_id",
    "er"."tenant_id",
    "er"."case_id",
    "er"."evidence_reference",
    "er"."evidence_title",
    "er"."evidence_type",
    "er"."evidence_status",
    "er"."privacy_level",
    "er"."uploaded_at" AS "event_occurred_at",
    'evidence_upload'::"text" AS "event_type"
   FROM "public"."evidence_records" "er"
  WHERE "public"."has_evidence_access"("er"."id")
UNION ALL
 SELECT "ete"."evidence_record_id",
    "ete"."tenant_id",
    "ete"."case_id",
    COALESCE("er"."evidence_reference", ("ete"."id")::"text") AS "evidence_reference",
    "ete"."event_title" AS "evidence_title",
    COALESCE("er"."evidence_type", "ete"."event_type") AS "evidence_type",
    COALESCE("er"."evidence_status", 'timeline'::"text") AS "evidence_status",
    COALESCE("er"."privacy_level", 'worker_only'::"text") AS "privacy_level",
    "ete"."event_occurred_at",
    "ete"."event_type"
   FROM ("public"."evidence_timeline_events" "ete"
     LEFT JOIN "public"."evidence_records" "er" ON (("er"."id" = "ete"."evidence_record_id")))
  WHERE (("ete"."evidence_record_id" IS NULL) OR "public"."has_evidence_access"("ete"."evidence_record_id"));


ALTER VIEW "public"."evidence_timeline_view" OWNER TO "postgres";


