CREATE OR REPLACE VIEW "public"."evidence_vault_dashboard_view" WITH ("security_invoker"='true') AS
 SELECT "tenant_id",
    "case_id",
    "count"(*) AS "evidence_count",
    "count"(*) FILTER (WHERE ("evidence_status" = 'pending_review'::"text")) AS "pending_verification_count",
    "count"(*) FILTER (WHERE ("legal_hold" = true)) AS "legal_hold_count",
    "count"(*) FILTER (WHERE (EXISTS ( SELECT 1
           FROM "public"."evidence_ai_analyses" "aia"
          WHERE (("aia"."evidence_record_id" = "er"."id") AND ("aia"."review_status" = 'pending_human_review'::"text"))))) AS "pending_ai_review_count",
    "count"(*) FILTER (WHERE (EXISTS ( SELECT 1
           FROM "public"."evidence_files" "ef"
          WHERE (("ef"."evidence_record_id" = "er"."id") AND ("ef"."integrity_status" <> ALL (ARRAY['verified'::"text", 'pending_verification'::"text"])))))) AS "integrity_warning_count"
   FROM "public"."evidence_records" "er"
  WHERE "public"."has_evidence_access"("id")
  GROUP BY "tenant_id", "case_id";


ALTER VIEW "public"."evidence_vault_dashboard_view" OWNER TO "postgres";


