CREATE TABLE IF NOT EXISTS "public"."media_evidence" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "case_id" "uuid" NOT NULL,
    "family_id" "uuid" NOT NULL,
    "child_id" "uuid",
    "consent_id" "uuid" NOT NULL,
    "media_type" "public"."media_evidence_type" NOT NULL,
    "source_type" "text" NOT NULL,
    "original_filename" "text" NOT NULL,
    "mime_type" "text" NOT NULL,
    "byte_size" bigint NOT NULL,
    "sha256" "text",
    "claimed_captured_at" timestamp with time zone,
    "extracted_captured_at" timestamp with time zone,
    "claimed_device" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "uploaded_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "uploaded_by" "uuid" NOT NULL,
    "upload_status" "text" DEFAULT 'initiated'::"text" NOT NULL,
    "integrity_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "safety_status" "public"."evidence_safety_status" DEFAULT 'quarantined'::"public"."evidence_safety_status" NOT NULL,
    "analysis_status" "public"."evidence_analysis_status" DEFAULT 'not_started'::"public"."evidence_analysis_status" NOT NULL,
    "retention_class" "text" DEFAULT 'case_evidence'::"text" NOT NULL,
    "legal_hold" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "media_evidence_byte_size_check" CHECK ((("byte_size" >= 1) AND ("byte_size" <= '10737418240'::bigint))),
    CONSTRAINT "media_evidence_check" CHECK ((("integrity_status" <> 'verified'::"text") OR (("sha256" IS NOT NULL) AND ("upload_status" = 'preserved'::"text")))),
    CONSTRAINT "media_evidence_cleared_requires_verified" CHECK ((("safety_status" <> 'cleared'::"public"."evidence_safety_status") OR ("integrity_status" = 'verified'::"text"))),
    CONSTRAINT "media_evidence_integrity_status_check" CHECK (("integrity_status" = ANY (ARRAY['pending'::"text", 'verified'::"text", 'verification_failed'::"text"]))),
    CONSTRAINT "media_evidence_original_filename_check" CHECK ((("length"("original_filename") >= 1) AND ("length"("original_filename") <= 255))),
    CONSTRAINT "media_evidence_sha256_check" CHECK (("sha256" ~ '^[a-f0-9]{64}$'::"text")),
    CONSTRAINT "media_evidence_source_type_check" CHECK (("source_type" = ANY (ARRAY['in_app_capture'::"text", 'device_upload'::"text", 'professional_upload'::"text"]))),
    CONSTRAINT "media_evidence_upload_status_check" CHECK (("upload_status" = ANY (ARRAY['initiated'::"text", 'preserving'::"text", 'preserved'::"text", 'failed'::"text"])))
);


