CREATE OR REPLACE VIEW "public"."platform_tenant_release_readiness_queue" WITH ("security_invoker"='true') AS
 SELECT "r"."id" AS "release_id",
    "r"."tenant_id",
    "t"."tenant_name",
    "r"."release_reference",
    "r"."release_version",
    "r"."release_channel",
    "r"."release_status",
    "r"."approved_by_user_id",
    (EXISTS ( SELECT 1
           FROM ("public"."platform_tenant_feature_flags" "f"
             JOIN "public"."platform_feature_definitions" "d" ON (("d"."id" = "f"."feature_definition_id")))
          WHERE (("f"."tenant_id" = "r"."tenant_id") AND (("d"."safety_critical" = true) OR ("d"."child_privacy_critical" = true)) AND ("f"."enabled" = false)))) AS "has_disabled_protected_feature",
    (EXISTS ( SELECT 1
           FROM "public"."platform_tenant_storage_policies" "sp"
          WHERE (("sp"."tenant_id" = "r"."tenant_id") AND ("sp"."active" = true)))) AS "has_storage_policy",
    (EXISTS ( SELECT 1
           FROM "public"."platform_tenant_data_retention_policies" "rp"
          WHERE (("rp"."tenant_id" = "r"."tenant_id") AND ("rp"."active" = true)))) AS "has_retention_policy"
   FROM ("public"."platform_tenant_deployment_releases" "r"
     JOIN "public"."platform_tenants" "t" ON (("t"."id" = "r"."tenant_id")))
  WHERE ("r"."release_status" = ANY (ARRAY['planned'::"text", 'pending_approval'::"text", 'ready'::"text"]));


ALTER VIEW "public"."platform_tenant_release_readiness_queue" OWNER TO "postgres";


