    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "story_goal" "text" DEFAULT ''::"text" NOT NULL,
    "strengths" "text" DEFAULT ''::"text" NOT NULL,
    "support_notes" "text" DEFAULT ''::"text" NOT NULL,
    "representation_preferences" "jsonb" DEFAULT '{"setupChoice": "choose_later", "familyStructure": "no_preference", "languagesSpoken": [], "culturalIdentity": "no_preference", "householdMembers": [], "parentCarerRoles": [], "preferredSkinTones": ["No preference"], "characterAppearance": [], "preferPeopleFreeIllustrations": false, "culturalClothingSettingsPractices": [], "aboriginalTorresStraitIslanderRepresentation": "no_preference"}'::"jsonb" NOT NULL,
    "auth_user_id" "uuid",
    "avatar_url" "text",
    "onboarding_status" "text" DEFAULT 'not_started'::"text" NOT NULL,
    "parenting_stage" "text",
    "contact_stage" "text",
    "risk_level" "text",
    "case_id" "uuid",
    "achievement_state" "jsonb",
