    "accessibility_preferences" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "notification_preferences" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "profile_status" "text" DEFAULT 'active'::"text" NOT NULL,
    "last_active_at" timestamp with time zone,
