CREATE OR REPLACE VIEW "public"."safety_dashboard_view" WITH ("security_invoker"='true') AS
 SELECT "c"."id" AS "case_id",
    "c"."tenant_id",
    "c"."case_reference",
    "sp"."id" AS "safety_plan_id",
    "sp"."safety_level",
    "sp"."next_review_at",
    "count"(DISTINCT "sa"."id") FILTER (WHERE ("sa"."alert_status" = 'open'::"text")) AS "open_alert_count",
    "count"(DISTINCT "si"."id") FILTER (WHERE ("si"."incident_status" = 'open'::"text")) AS "open_incident_count",
    "count"(DISTINCT "wrd"."id") FILTER (WHERE ("wrd"."review_status" = 'pending_review'::"text")) AS "pending_weapon_alert_count",
    "count"(DISTINCT "mce"."id") FILTER (WHERE ("mce"."event_status" = 'open'::"text")) AS "open_missing_child_count",
    "count"(DISTINCT "srf"."id") FILTER (WHERE ("srf"."current_status" = 'active'::"text")) AS "active_risk_factor_count",
    "count"(DISTINCT "spf"."id") FILTER (WHERE ("spf"."active" = true)) AS "active_protective_factor_count"
   FROM ((((((("public"."cases" "c"
     LEFT JOIN "public"."safety_plans" "sp" ON ((("sp"."case_id" = "c"."id") AND ("sp"."plan_status" = 'active'::"text"))))
     LEFT JOIN "public"."safety_alerts" "sa" ON (("sa"."case_id" = "c"."id")))
     LEFT JOIN "public"."safety_incidents" "si" ON (("si"."case_id" = "c"."id")))
     LEFT JOIN "public"."weapon_risk_detections" "wrd" ON (("wrd"."case_id" = "c"."id")))
     LEFT JOIN "public"."missing_child_events" "mce" ON (("mce"."case_id" = "c"."id")))
     LEFT JOIN "public"."safety_risk_factors" "srf" ON (("srf"."case_id" = "c"."id")))
     LEFT JOIN "public"."safety_protective_factors" "spf" ON (("spf"."case_id" = "c"."id")))
  WHERE "public"."has_safety_access"("c"."id")
  GROUP BY "c"."id", "c"."tenant_id", "c"."case_reference", "sp"."id", "sp"."safety_level", "sp"."next_review_at";


