CREATE OR REPLACE VIEW "public"."supervisor_caseload_view" WITH ("security_invoker"='true') AS
 SELECT "c"."id" AS "case_id",
    "c"."case_reference",
    "c"."case_status_code",
    "c"."priority_code",
    "primary_worker"."allocated_user_id" AS "primary_worker_user_id",
    "supervisor"."allocated_user_id" AS "supervisor_user_id",
    "c"."target_review_at",
        CASE
            WHEN ("c"."target_review_at" < "now"()) THEN true
            ELSE false
        END AS "review_overdue"
   FROM (("public"."cases" "c"
     LEFT JOIN "public"."case_allocations" "primary_worker" ON ((("primary_worker"."case_id" = "c"."id") AND ("primary_worker"."allocation_role" = 'primary_worker'::"text") AND ("primary_worker"."allocation_status" = 'active'::"text") AND ("primary_worker"."ended_at" IS NULL))))
     LEFT JOIN "public"."case_allocations" "supervisor" ON ((("supervisor"."case_id" = "c"."id") AND ("supervisor"."allocation_role" = 'primary_supervisor'::"text") AND ("supervisor"."allocation_status" = 'active'::"text") AND ("supervisor"."ended_at" IS NULL))));


