    "practice_task" "text" NOT NULL,
    "optional_evidence_upload_types" "jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "attribution_review_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "clinical_review_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "cultural_review_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    CONSTRAINT "video_resources_attribution_review_status_check" CHECK (("attribution_review_status" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'changes_required'::"text"]))),
    CONSTRAINT "video_resources_clinical_review_status_check" CHECK (("clinical_review_status" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'changes_required'::"text"]))),
    CONSTRAINT "video_resources_cultural_review_status_check" CHECK (("cultural_review_status" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'changes_required'::"text"]))),
    CONSTRAINT "video_resources_download_permission_check" CHECK (("download_permission" = false)),
    CONSTRAINT "video_resources_editing_permission_check" CHECK (("editing_permission" = false)),
    CONSTRAINT "video_resources_embed_code_status_check" CHECK (("embed_code_status" = ANY (ARRAY['missing'::"text", 'pending_review'::"text", 'verified'::"text", 'failed'::"text"]))),
    CONSTRAINT "video_resources_publication_status_check" CHECK (("publication_status" = ANY (ARRAY['draft'::"text", 'approved'::"text", 'published'::"text", 'retired'::"text"]))),
    CONSTRAINT "video_resources_publish_requires_captions" CHECK ((("publication_status" <> 'published'::"text") OR ("captions_verified" = true))),
    CONSTRAINT "video_resources_publish_requires_embed_url" CHECK ((("publication_status" <> 'published'::"text") OR ("embed_url" IS NOT NULL))),
    CONSTRAINT "video_resources_publish_requires_review" CHECK ((("publication_status" <> 'published'::"text") OR ("licence_checked_at" IS NOT NULL))),
    CONSTRAINT "video_resources_publish_requires_verified_embed" CHECK ((("publication_status" <> 'published'::"text") OR ("embed_code_status" = 'verified'::"text"))),
    CONSTRAINT "video_resources_rehosting_permission_check" CHECK (("rehosting_permission" = false)),
    CONSTRAINT "video_resources_requires_five_questions" CHECK (("jsonb_array_length"("knowledge_check") = 5))
);


ALTER TABLE "public"."video_resources" OWNER TO "postgres";


