CREATE OR REPLACE VIEW "public"."worker_caseload_view" WITH ("security_invoker"='true') AS
 SELECT "c"."id" AS "case_id",
    "c"."tenant_id",
    "c"."case_reference",
    "c"."case_title",
    "c"."case_type_code",
    "c"."case_status_code",
    "c"."priority_code",
    "c"."opened_at",
    "c"."target_review_at",
    "f"."id" AS "family_id",
    "f"."family_display_name",
    "ca"."allocated_user_id",
    "ca"."allocation_role",
    "ca"."primary_allocation",
    ( SELECT "count"(*) AS "count"
           FROM (("public"."case_plan_actions" "cpa"
             JOIN "public"."case_plan_goals" "cpg" ON (("cpg"."id" = "cpa"."case_plan_goal_id")))
             JOIN "public"."case_plans" "cp" ON (("cp"."id" = "cpg"."case_plan_id")))
          WHERE (("cp"."case_id" = "c"."id") AND ("cpa"."action_status" <> ALL (ARRAY['completed'::"text", 'cancelled'::"text"])))) AS "open_action_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."case_barriers" "cb"
          WHERE (("cb"."case_id" = "c"."id") AND ("cb"."barrier_status" = 'active'::"text"))) AS "active_barrier_count"
   FROM (("public"."cases" "c"
     JOIN "public"."families" "f" ON (("f"."id" = "c"."family_id")))
     JOIN "public"."case_allocations" "ca" ON ((("ca"."case_id" = "c"."id") AND ("ca"."allocation_status" = 'active'::"text") AND ("ca"."ended_at" IS NULL))));


ALTER VIEW "public"."worker_caseload_view" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."worker_child_voice_queue" WITH ("security_invoker"='true') AS
 SELECT "id" AS "request_id",
    "request_reference",
    "child_id",
    "request_category",
    "system_safety_priority",
    "status",
    "submitted_at",
    "acknowledged_at"
   FROM "public"."child_support_requests" "r"
  WHERE ("status" = ANY (ARRAY['submitted'::"text", 'acknowledged'::"text", 'under_review'::"text"]));


ALTER VIEW "public"."worker_child_voice_queue" OWNER TO "postgres";


