CREATE INDEX "assessment_records_case_instrument_date_idx" ON "public"."assessment_records" USING "btree" ("case_id", "instrument_id", "assessment_date" DESC) WHERE ("status" = 'completed'::"text");



CREATE INDEX "audit_events_actor_idx" ON "public"."audit_events" USING "btree" ("actor_user_id", "occurred_at" DESC);



CREATE INDEX "audit_events_target_idx" ON "public"."audit_events" USING "btree" ("target_table", "target_record_id");



CREATE INDEX "audit_events_tenant_time_idx" ON "public"."audit_events" USING "btree" ("tenant_id", "occurred_at" DESC);



CREATE UNIQUE INDEX "care_arrangements_one_active_primary_idx" ON "public"."care_arrangements" USING "btree" ("tenant_id", "child_id") WHERE (("primary_arrangement" = true) AND ("care_status" = 'active'::"text"));



CREATE INDEX "case_allocations_case_idx" ON "public"."case_allocations" USING "btree" ("tenant_id", "case_id", "allocation_status");



